sed -i 's/<div class="interview-sidebar">/<div class="interview-sidebar">\n<script>\nfunction showPRDMock(id) {\n  const el = document.getElementById("prd-mock-content");\n  if(id === "prd") {\n    el.innerHTML = "<h1>Product Requirements Document</h1><p><strong>Status:</strong> Approved | <strong>Version:</strong> 1.0</p><h2>1. Executive Summary</h2><p>Puppet Master is a cross-platform desktop IDE designed to orchestrate AI agents for automated coding. It leverages Rust and Slint for a highly responsive user experience.</p><h2>2. Functional Requirements</h2><p><ul><li>FR1: The system shall support 5 tier phases for execution.</li><li>FR2: It must integrate with Cursor, Gemini, and Codex natively.</li><li>FR3: A visual DAG representation of tasks must be provided.</li></ul></p><h2>3. Non-Functional Requirements</h2><p><ul><li>NFR1: GUI updates must render at 60fps.</li><li>NFR2: Application launch time must be under 500ms.</li></ul></p><h2>4. Out of Scope</h2><p>Mobile application support is deferred to v2.0.</p>";\n  } else if(id === "seeds") {\n    el.innerHTML = "<h1>Contract Seeds</h1><p>These JSON artifacts lock in the decisions for the execution phase.</p><pre style=\"background:var(--surface); padding:var(--md); font-family:monospace; font-size:11px;\">{\n  \"schema_version\": \"1.0\",\n  \"tier_config\": {\n    \"auto_approve\": false,\n    \"branching\": \"feature\"\n  }\n}</pre>";\n  } else if(id === "arch") {\n    el.innerHTML = "<h1>Architecture Documentation</h1><h2>1. Core Systems</h2><p>We are using a Rust backend connected to a Slint UI via channels. Persistent state is maintained using `redb`.</p><h2>2. Component Diagram</h2><div class=\"mock-mermaid\">graph TD;<br>UI[Slint Window] -->|Events| Backend[Rust Core];<br>Backend --> DB[(Redb)];<br>Backend --> Agents{{Agent Subsystem}};</div>";\n  }\n  document.querySelectorAll(".prd-pill").forEach(p => p.classList.remove("active"));\n  document.getElementById("pill-" + id).classList.add("active");\n}\n</script>/' Concepts/PuppetMasterDashComp.html
